16: </head>
17: <body>
18:   <canvas id="canvas" width="640" height="400" tabindex="0"></canvas>
19:   <div id="status">Loading…</div>
20:   <div class="toolbar" aria-label="Game controls">
21:     <button id="menu" disabled>Menu</button>
22:     <button id="pause" disabled aria-pressed="false">Pause</button>
23:     <button id="sound" aria-pressed="false">Enable sound</button>
24:     <label>Volume <input id="volume" type="range" min="0" max="100" value="70"></label>
25:   </div>
26:   <div id="controls">Arrows: move/turn · W/S: forward/back · A/D: strafe · Ctrl: fire · Space: use<br>Shift: run · 1–7: weapon · Tab: map · Enter/Esc: menus · P: pause</div>
27:   <script src="audio.js"></script>
28:   <script>
29:     // Browser KeyboardEvent.code -> Doom key code (doomkeys.h)
30:     const MAP = {
31:       ArrowLeft: 0xac, ArrowRight: 0xae, ArrowUp: 0xad, ArrowDown: 0xaf,
32:       ControlLeft: 0xa3, ControlRight: 0xa3, Space: 0xa2,
33:       Comma: 0xa0, Period: 0xa1,
34:       KeyW: 0xad, KeyS: 0xaf, KeyA: 0xa0, KeyD: 0xa1, KeyP: 0xff,
35:       Enter: 13, NumpadEnter: 13, Escape: 27, Tab: 9, Backspace: 0x7f,
36:       ShiftLeft: 0x80 + 0x36, ShiftRight: 0x80 + 0x36,
37:       AltLeft: 0x80 + 0x38, AltRight: 0x80 + 0x38,
38:       Minus: 0x2d, Equal: 0x3d, Pause: 0xff,
39:       F1: 0xbb, F2: 0xbc, F3: 0xbd, F4: 0xbe, F5: 0xbf, F6: 0xc0,
40:       F7: 0xc1, F8: 0xc2, F9: 0xc3, F10: 0xc4, F11: 0xd7, F12: 0xd8,
41:     };
42:     function doomKey(e) {
43:       if (MAP[e.code] !== undefined) return MAP[e.code];
44:       if (/^Key[A-Z]$/.test(e.code)) return e.code.charCodeAt(3) + 32; // lowercase
45:       if (/^Digit[0-9]$/.test(e.code)) return e.code.charCodeAt(5);
46:       return 0;
47:     }
48:     const down = new Map(); // physical key -> Doom key; aliases may overlap
49:     function unlockAudio() {
50:       DoomAudio.unlock().catch(error => { document.getElementById('status').textContent = `Sound unavailable: ${error.message}`; });
51:     }
52:     function release(code) {
53:       const k = down.get(code);
54:       if (k === undefined) return;
55:       down.delete(code);
56:       if (![...down.values()].includes(k)) Module._dg_key(0, k);
57:     }
58:     function send(pressed, e) {
59:       if (!pressed) { release(e.code); return; }
60:       if (e.target.closest?.('button, input, select, textarea')) return;
61:       const k = doomKey(e);
62:       if (!k || !Module._dg_key || e.metaKey) return;
63:       if (['F5','F11','F12'].includes(e.code)) return;
64:       e.preventDefault(); unlockAudio();
65:       if (down.has(e.code)) return;
66:       const held = [...down.values()].includes(k);
67:       down.set(e.code, k);
68:       if (!held) Module._dg_key(1, k);
69:     }
70:     window.addEventListener('keydown', e => send(true, e));
71:     window.addEventListener('keyup', e => send(false, e));
72:     function releaseAll() {
73:       for (const k of new Set(down.values())) Module._dg_key(0, k);
74:       down.clear();
75:     }
76:     window.addEventListener('blur', releaseAll);
77:     document.addEventListener('visibilitychange', () => { if (document.hidden) releaseAll(); });
78:     document.getElementById('canvas').addEventListener('pointerdown', unlockAudio);
79:     function buttonKey(k) {
80:       if (!Module._dg_key) return;
81:       unlockAudio(); Module._dg_key(1, k);
82:       setTimeout(() => Module._dg_key(0, k), 70);
83:       Module.canvas.focus();
84:     }
85:     document.getElementById('menu').addEventListener('click', () => buttonKey(27));
86:     document.getElementById('pause').addEventListener('click', () => buttonKey(255));
87:     document.getElementById('sound').addEventListener('click', () => {
88:       if (DoomAudio.context) DoomAudio.setMuted(!DoomAudio.muted);
89:       unlockAudio();
90:     });
91:     document.getElementById('volume').addEventListener('input', e => DoomAudio.setVolume(Number(e.target.value)/100));
92:     setInterval(() => {
93:       if (!Module._dg_paused) return;
94:       const paused = !!Module._dg_paused(), button = document.getElementById('pause');
95:       button.textContent = paused ? 'Resume' : 'Pause'; button.setAttribute('aria-pressed', String(paused));
96:     }, 100);
97: 
98:     var Module = {
99:       canvas: document.getElementById('canvas'),
100:       onAbort: w => { document.getElementById('status').textContent = `Game stopped: ${w}`; },
101:       print: t => console.log(t),
102:       printErr: t => console.warn(t),
103:       setStatus: t => { document.getElementById('status').textContent = t || 'Ready — click the game or press a key to enable sound'; },
104:       monitorRunDependencies: n => { if (n === 0) document.getElementById('status').textContent = 'Arrows move, Ctrl fire, Space use, Enter/Esc menu'; },
105:       onRuntimeInitialized: () => {
